"""S10: docs/generation_modes.html, generated by scripts/make_generation_doc.py from rate_table().

Contract with the generator: every rate entry is an element with data-codec, data-n and data-rate-hz attributes; atoms
entries also carry data-atom-latents, data-crossfade-ms and data-k-max. Worked examples sit in elements with a data-example
attribute.
Run from SCAPES/: ../venv_SCAPES/bin/python -m pytest tests_v3/test_generation_doc.py -q
"""
import html
import math
import re
from html.parser import HTMLParser
from pathlib import Path

import pytest

REPO = Path(__file__).resolve().parents[1]
PAGE = REPO / "docs" / "generation_modes.html"
USER = ["encodec24", "spectrostream", "encodec48", "music2latent"]


class _Collect(HTMLParser):
    def __init__(self):
        super().__init__()
        self.entries, self.examples = [], 0

    def handle_starttag(self, tag, attrs):
        a = dict(attrs)
        if "data-codec" in a and "data-n" in a:
            self.entries.append(a)
        if "data-example" in a:
            self.examples += 1


@pytest.fixture(scope="module")
def page():
    return PAGE.read_text()


def test_page_parses_offline(page):
    p = _Collect()
    p.feed(page)
    assert not re.search(r"""(src|href)\s*=\s*["']https?:""", page, re.I), "the page must not load external assets"
    assert "grain" not in page.lower()


@pytest.mark.parametrize("codec", USER)
def test_every_rate_listed(page, codec):
    from SCAPES.generation import CODECS, rate_table
    p = _Collect()
    p.feed(page)
    entries = {int(a["data-n"]): a for a in p.entries if a["data-codec"] == codec}
    rows = rate_table(codec)
    assert sorted(entries) == [r["n"] for r in rows]
    for row in rows:
        a = entries[row["n"]]
        assert math.isclose(float(a["data-rate-hz"]), row["rate_hz"], rel_tol=1e-6), row["n"]
        if CODECS[codec].mode == "atoms":
            assert int(a["data-atom-latents"]) == row["atom_latents"]
            assert abs(float(a["data-crossfade-ms"]) - row["crossfade_ms"]) <= 0.5
            assert int(a["data-k-max"]) == row["k_max"]


def test_diagrams_formulas_cap_examples(page):
    svgs = re.findall(r"<svg.*?</svg>", page, re.S | re.I)
    assert len(svgs) >= 2
    assert any("Autoregressive" in s for s in svgs) and any("Atoms" in s for s in svgs)
    text = html.unescape(re.sub(r"<[^>]+>", " ", page))
    assert "300" in text and "cap" in text.lower()
    p = _Collect()
    p.feed(page)
    assert p.examples >= 4
    for needle in ("n = 13", "11.54 Hz", "n = 4", "2.69 Hz", "5.00 Hz", "K = 50"):
        assert needle in text, needle
    assert "crossfade_window" in text and "equal power" in text.lower()      # the one window function (D8)

